            runtime is CrossRuntimeReviewRuntimes.Copilot or CrossRuntimeReviewRuntimes.Opencode
                ? "pass a valid --effort value for the runtime."
                : "omit --effort for this runtime.");
        return false;
    }

    return true;
}

