        {
            var relative = Path.GetRelativePath(RepoVersionPolicySource.RepoRoot(), path).Replace('\\', '/');
            if (!IsSurfaceFile(relative))
            {
                continue;
            }

            foreach (var typeName in declaredTypes)
            {
